impl flatbuffers::Verifiable for Envelope<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<u16>("protocol_version", Self::VT_PROTOCOL_VERSION, false)?
     .visit_field::<u64>("sequence", Self::VT_SEQUENCE, false)?
     .visit_field::<u64>("request_id", Self::VT_REQUEST_ID, false)?
     .visit_union::<Payload, _>("payload_type", Self::VT_PAYLOAD_TYPE, "payload", Self::VT_PAYLOAD, false, |key, v, pos| {
        match key {
          Payload::InputLayout => v.verify_union_variant::<flatbuffers::ForwardsUOffset<InputLayout>>("Payload::InputLayout", pos),
          Payload::WindowSnapshot => v.verify_union_variant::<flatbuffers::ForwardsUOffset<WindowSnapshot>>("Payload::WindowSnapshot", pos),
          Payload::DisplayLayout => v.verify_union_variant::<flatbuffers::ForwardsUOffset<DisplayLayout>>("Payload::DisplayLayout", pos),
          Payload::WindowRequest => v.verify_union_variant::<flatbuffers::ForwardsUOffset<WindowRequest>>("Payload::WindowRequest", pos),
          Payload::WindowResponse => v.verify_union_variant::<flatbuffers::ForwardsUOffset<WindowResponse>>("Payload::WindowResponse", pos),
          Payload::WindowEvent => v.verify_union_variant::<flatbuffers::ForwardsUOffset<WindowEvent>>("Payload::WindowEvent", pos),
          Payload::ShellAction => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ShellAction>>("Payload::ShellAction", pos),
          Payload::CursorShape => v.verify_union_variant::<flatbuffers::ForwardsUOffset<CursorShape>>("Payload::CursorShape", pos),
          Payload::KeyboardCommand => v.verify_union_variant::<flatbuffers::ForwardsUOffset<KeyboardCommand>>("Payload::KeyboardCommand", pos),
          Payload::CursorPosition => v.verify_union_variant::<flatbuffers::ForwardsUOffset<CursorPosition>>("Payload::CursorPosition", pos),
          Payload::DesktopNotificationEvent => v.verify_union_variant::<flatbuffers::ForwardsUOffset<DesktopNotificationEvent>>("Payload::DesktopNotificationEvent", pos),
          Payload::DesktopNotificationCommand => v.verify_union_variant::<flatbuffers::ForwardsUOffset<DesktopNotificationCommand>>("Payload::DesktopNotificationCommand", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
